#!/usr/bin/env python3
# SPDX-License-Identifier: MIT OR Apache-2.0
"""Compare the committed tables with the same tables generated by the engine.

This is the gate for the work in `FIX_GENGAPS.md`: before a generator is
allowed to stop reading the Kotus/Omorfi sqlite, the committed output and the
engine output are compared, and every lost surface or base is explained.

The script regenerates the engine output into a temporary directory, then
reports:

    committed / engine / shared / lost / new

for the artifacts that already have an engine path:

* `all_forms.csv`            — by unique surface and by row
* `stem_to_base_map.csv`     — by `(stem, base)` and by distinct base
* `adj_degrees.csv`          — by degree cell (comparative, superlative)

Lost bases are bucketed from `data/nykysuomensanalista.csv` so a classless
compound (G1) is not confused with a classed nominal (G1b) or a word the
sanalista does not have.

`--strict` fails when an artifact loses more than the recorded baseline. That
lets the known gaps stay visible without making every run red; when a gap is
closed, lower the baseline in the same commit.

Usage:
    python3 tools/build/compare_engine_outputs.py
    python3 tools/build/compare_engine_outputs.py --artifact all_forms
    python3 tools/build/compare_engine_outputs.py --strict
"""

from __future__ import annotations

import argparse
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
BUILD = REPO / "tools" / "build"
SANALISTA = REPO / "data" / "nykysuomensanalista.csv"

#: Largest expected loss per artifact on the 2026-11-05 baseline. A number
#: that grows means a new regression; a number that shrinks should be edited
#: down here in the commit that closes the gap.
BASELINE = {
    "all_forms": 12_707,
    # Classed nominal bases the engine cannot produce. Classless compounds
    # are not counted: they resolve through their head, not as map bases.
    "stem_map_noun_classed": 0,
    "adj_degrees": 0,
}


def run(builder: str, *args: str) -> None:
    subprocess.run(
        [sys.executable, str(BUILD / builder), *args],
        check=True,
        cwd=REPO,
    )


def lines(path: Path) -> list[str]:
    return path.read_text(encoding="utf-8").splitlines()


def forms(path: Path) -> set[str]:
    return {line.split("\t", 1)[0] for line in lines(path) if line}


def pairs(path: Path) -> set[tuple[str, str]]:
    out: set[tuple[str, str]] = set()
    for line in lines(path):
        if not line:
            continue
        cols = line.split("\t")
        if len(cols) >= 2:
            out.add((cols[0], cols[1]))
    return out


def sanalista_rows() -> dict[str, str]:
    """base -> the inflection column (empty for a classless row)."""
    rows: dict[str, str] = {}
    for line in SANALISTA.read_text(encoding="utf-8").splitlines():
        cols = line.split("\t")
        if cols and cols[0]:
            rows.setdefault(cols[0], cols[3].strip() if len(cols) > 3 else "")
    return rows


def report(
    label: str,
    committed: set,
    engine: set,
    strict: bool,
    baseline: int,
) -> bool:
    lost = committed - engine
    new = engine - committed
    print(
        f"{label}: committed={len(committed)} engine={len(engine)} "
        f"shared={len(committed & engine)} lost={len(lost)} new={len(new)}"
    )
    for item in sorted(lost)[:5]:
        print(f"  lost sample: {item}")
    if strict and len(lost) > baseline:
        print(
            f"  FAIL: {len(lost)} lost, baseline is {baseline} "
            f"(a new regression, or lower the baseline if intended)",
            file=sys.stderr,
        )
        return False
    return True


def compare_all_forms(tmp: Path, strict: bool) -> bool:
    engine_csv = tmp / "all_forms_engine.csv"
    run("build_all_forms_csv.py", "--out", str(engine_csv))
    old = REPO / "data" / "all_forms.csv"
    ok = report(
        "all_forms (unique surfaces)",
        forms(old),
        forms(engine_csv),
        strict,
        BASELINE["all_forms"],
    )
    print(
        f"all_forms (rows): committed={len(lines(old))} "
        f"engine={len(lines(engine_csv))}"
    )
    return ok


def degree_cells(path: Path) -> tuple[set[tuple[str, str]], set[tuple[str, str]]]:
    """`(positive, comparative)` and `(positive, superlative)` pairs."""
    comp: set[tuple[str, str]] = set()
    sup: set[tuple[str, str]] = set()
    rows = path.read_text(encoding="utf-8").splitlines()[1:]
    for line in rows:
        cols = line.split("\t")
        if len(cols) < 3:
            continue
        if cols[1]:
            comp.add((cols[0], cols[1]))
        if cols[2]:
            sup.add((cols[0], cols[2]))
    return comp, sup


def compare_adj_degrees(tmp: Path, strict: bool) -> bool:
    engine_csv = tmp / "adj_degrees_engine.csv"
    run("build_adj_degrees.py", "--out", str(engine_csv))
    old_comp, old_sup = degree_cells(REPO / "data" / "adj_degrees.csv")
    new_comp, new_sup = degree_cells(engine_csv)
    ok = report(
        "adj_degrees (comparatives)",
        old_comp,
        new_comp,
        strict,
        BASELINE["adj_degrees"],
    )
    ok &= report(
        "adj_degrees (superlatives)",
        old_sup,
        new_sup,
        strict,
        BASELINE["adj_degrees"],
    )
    return ok


def compare_stem_map_noun(tmp: Path, strict: bool) -> bool:
    engine_csv = tmp / "stem_map_noun_engine.csv"
    run(
        "build_stem_to_base_map.py",
        "--source",
        "engine",
        "--out",
        str(engine_csv),
    )
    old = pairs(REPO / "data" / "stem_to_base_map.csv")
    new = pairs(engine_csv)
    print(
        f"stem_map_noun (pairs): committed={len(old)} engine={len(new)} "
        f"shared={len(old & new)} lost={len(old - new)} new={len(new - old)}"
    )

    old_bases = {b for _, b in old}
    new_bases = {b for _, b in new}
    lost_bases = old_bases - new_bases
    sanalista = sanalista_rows()
    classless = sorted(b for b in lost_bases if sanalista.get(b) == "")
    classed = sorted(b for b in lost_bases if b in sanalista and sanalista[b] != "")
    unknown = sorted(b for b in lost_bases if b not in sanalista)
    print(
        f"stem_map_noun (bases): committed={len(old_bases)} "
        f"engine={len(new_bases)} lost={len(lost_bases)} "
        f"[classless(by head)={len(classless)} classed={len(classed)} "
        f"not-in-sanalista={len(unknown)}]"
    )
    print(
        "  classless bases resolve through their compound head, so they are "
        "not expected as map bases"
    )
    for label, bucket in (
        ("classless", classless),
        ("classed", classed),
        ("not-in-sanalista", unknown),
    ):
        if bucket:
            print(f"  {label} sample: {bucket[:5]}")

    ok = True
    limit = BASELINE["stem_map_noun_classed"]
    if strict and len(classed) > limit:
        print(
            f"  FAIL: {len(classed)} classed bases lost, baseline is {limit}",
            file=sys.stderr,
        )
        ok = False
    if strict and unknown:
        print(
            f"  FAIL: {len(unknown)} lost bases are not in the sanalista",
            file=sys.stderr,
        )
        ok = False
    return ok


def main(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    ap.add_argument(
        "--artifact",
        choices=("all", "all_forms", "stem_map_noun", "adj_degrees"),
        default="all",
    )
    ap.add_argument(
        "--strict",
        action="store_true",
        help="fail when an artifact loses more than the recorded baseline",
    )
    ap.add_argument(
        "--keep",
        metavar="DIR",
        help="write the engine output here instead of a temporary directory",
    )
    args = ap.parse_args(argv)

    if args.keep:
        tmp = Path(args.keep)
        tmp.mkdir(parents=True, exist_ok=True)
    else:
        # The system /tmp may be a small tmpfs; prefer the approved work dir
        # when it exists. `all_forms` alone is ~300 MB.
        base = Path("/tmp/opencode")
        tmp = Path(
            tempfile.mkdtemp(
                prefix="torille-compare-",
                dir=base if base.is_dir() else None,
            )
        )

    ok = True
    if args.artifact in ("all", "all_forms"):
        ok &= compare_all_forms(tmp, args.strict)
    if args.artifact in ("all", "stem_map_noun"):
        ok &= compare_stem_map_noun(tmp, args.strict)
    if args.artifact in ("all", "adj_degrees"):
        ok &= compare_adj_degrees(tmp, args.strict)

    if args.keep:
        print(f"engine output in {tmp}")
    else:
        shutil.rmtree(tmp, ignore_errors=True)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
